package com.acme.shortener.analytics;

import com.acme.shortener.auth.ApiKeyAuthInterceptor;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.Parameter;
import io.swagger.v3.oas.annotations.security.SecurityRequirement;
import io.swagger.v3.oas.annotations.tags.Tag;
import java.time.LocalDate;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestAttribute;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Tag(name = "Links")
@SecurityRequirement(name = "apiKey")
class StatsController {

  private final StatsService stats;

  StatsController(StatsService stats) {
    this.stats = stats;
  }

  @GetMapping("/api/v1/links/{code}/stats")
  @Operation(
      summary = "Click stats for a link",
      description =
          "Days are UTC, both ends inclusive; the default is the last 30 days, the maximum 90."
              + " Clicks appear about a second after the redirect. uniqueVisitors is approximate"
              + " (HyperLogLog), and a visitor seen on two days counts twice.")
  LinkStats stats(
      @PathVariable String code,
      @RequestParam(required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate from,
      @RequestParam(required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate to,
      @Parameter(hidden = true) @RequestAttribute(ApiKeyAuthInterceptor.PRINCIPAL) String owner) {
    return stats.stats(code, owner, from, to);
  }

  @GetMapping(value = "/api/v1/links/{code}/stats.csv", produces = "text/csv")
  @Operation(
      summary = "Daily clicks of a link as CSV",
      description =
          "A day,clicks header, then one row per UTC day of the range, oldest first, zero-filled."
              + " Same range rules, defaults and errors as the JSON stats.")
  ResponseEntity<String> statsCsv(
      @PathVariable String code,
      @RequestParam(required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate from,
      @RequestParam(required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate to,
      @Parameter(hidden = true) @RequestAttribute(ApiKeyAuthInterceptor.PRINCIPAL) String owner) {
    LinkStats linkStats = stats.stats(code, owner, from, to);
    return ResponseEntity.ok()
        .contentType(new MediaType("text", "csv", java.nio.charset.StandardCharsets.UTF_8))
        .header(
            HttpHeaders.CONTENT_DISPOSITION,
            ContentDisposition.attachment()
                .filename(linkStats.code() + "-clicks.csv")
                .build()
                .toString())
        .body(StatsCsv.dailyClicks(linkStats));
  }
}

package com.acme.shortener.analytics;

/**
 * A link's daily clicks as CSV: a {@code day,clicks} header, then one row per day, oldest first.
 */
final class StatsCsv {

  static final String HEADER = "day,clicks";

  private StatsCsv() {}

  /** LF line endings and ISO dates, so the output is the same on every platform. */
  static String dailyClicks(LinkStats stats) {
    StringBuilder csv = new StringBuilder(HEADER).append('\n');
    for (LinkStats.DayClicks day : stats.clicksByDay()) {
      csv.append(day.day()).append(',').append(day.clicks()).append('\n');
    }
    return csv.toString();
  }
}
